[CmdletBinding()]
param([Parameter(Mandatory)][string]$AccountHome,[Parameter(Mandatory)][string]$State,[string]$ExpectedEmail)
$ErrorActionPreference='Stop'
$exe=Get-ChildItem (Join-Path $AccountHome 'packages\app-server-daemon\releases') -Filter codex.exe -Recurse -File -EA SilentlyContinue|Select-Object -First 1 -ExpandProperty FullName
if(-not $exe){$exe=Get-ChildItem (Join-Path $env:USERPROFILE '.codex\packages\app-server-daemon\releases') -Filter codex.exe -Recurse -File|Select-Object -First 1 -ExpandProperty FullName}
if(-not $exe){throw 'Codex app-server executable not found'}
$si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$exe;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardInput=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.Environment['CODEX_HOME']=$AccountHome
if($si.ArgumentList){foreach($x in @('app-server','--listen','stdio://','-c',('sqlite_home="'+$State+'"'))){[void]$si.ArgumentList.Add($x)}}else{$si.Arguments='app-server --listen stdio:// -c sqlite_home="'+$State+'"'}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;[void]$p.Start()
try{$errTask=$p.StandardError.ReadToEndAsync();$p.StandardInput.WriteLine('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"clientInfo":{"name":"codex-account-manager","title":"Codex Account Manager","version":"0.5.0"}}}');$p.StandardInput.WriteLine('{"jsonrpc":"2.0","method":"initialized","params":{}}');$p.StandardInput.WriteLine('{"jsonrpc":"2.0","id":2,"method":"account/read","params":{}}');$p.StandardInput.Flush();$deadline=(Get-Date).AddSeconds(40);$account=$null;$read=$p.StandardOutput.ReadLineAsync();while((Get-Date)-lt$deadline){if($read.Wait(500)){$line=$read.Result;if([string]::IsNullOrEmpty($line)){throw 'App Server returned an empty response'};$read=$p.StandardOutput.ReadLineAsync();try{$j=$line|ConvertFrom-Json}catch{throw 'Invalid JSON from App Server'};if($j.error){throw 'JSON-RPC error during account/read'};if($j.id -eq 2){$account=$j.result.account;break}};if($p.HasExited){$err=if($errTask.Wait(1000)){$errTask.Result.Trim()}else{'stderr still open'};throw "App Server exited before account/read: $err"}};if(-not $account){$err=if($errTask.Wait(1000)){$errTask.Result.Trim()}else{'stderr still open'};throw "account/read timeout; stderr=$err"};if(-not $account.email){throw 'account/read returned no email'};$email=[string]$account.email;if($ExpectedEmail -and $email.Trim().ToLowerInvariant() -ne $ExpectedEmail.Trim().ToLowerInvariant()){throw 'Authenticated email does not match expected email'};[pscustomobject]@{Email=$email;Plan=[string]$account.planType;Verified=$true}|ConvertTo-Json -Compress}finally{if(-not$p.HasExited){$p.Kill()};if($errTask){$errTask.Wait(1000)|Out-Null};$p.Dispose()}
